var accountClassificationId = Get<Guid>("AccountClassification");
var workingDaysToAdd = 0;
if (accountClassificationId == PgrConstants.AccountClassification.A)
{
	workingDaysToAdd = 3;
}
else if (accountClassificationId == PgrConstants.AccountClassification.B ||
			         accountClassificationId == PgrConstants.AccountClassification.C)
{
	workingDaysToAdd = 5;
}

var userConnection = context.UserConnection;
var calendarUtils = new PgrCalendarServiceUtils(userConnection);
var baseCalendarId = (Guid) SysSettings.GetValue(userConnection, "BaseCalendar");
var calendarId = baseCalendarId == Guid.Empty ? PgrConstants.Calendar.StandardCalendar : baseCalendarId;
var currentDate = DateTime.Now;
var endDate = calendarUtils.AddWorkingDays(currentDate, workingDaysToAdd, calendarId);
var taskDurationInDays = endDate.Subtract(currentDate).Days;
Set("TaskDurationInDays", taskDurationInDays);

return true;
